local function resolve(path)
	local q=preview
	for _,n in ipairs(path) do q=q:WaitForChild(n) end
	return q
end
local restored=0
for _,g in ipairs(GROUPS) do
	local parent=resolve(g[1])
	local count=0
	for _,q in ipairs(parent:GetChildren()) do if q:IsA("BasePart") then count+=1 end end
	if count==0 then
		for _,s in ipairs(g[2]) do
			local q=Instance.new(s[1])
			q.Name=s[2] q.Size=s[3] q.CFrame=s[4] q.Color=s[5] q.Material=s[6]
			q.Transparency=s[7]
			if q:IsA("Part") and s[8] then q.Shape=s[8] end
			q.Anchored=true q.CanCollide=false q.CanTouch=false q.CanQuery=false
			q.TopSurface=Enum.SurfaceType.Smooth q.BottomSurface=Enum.SurfaceType.Smooth
			q.Parent=parent restored+=1
		end
	end
end

local core=fire.WindowFlames:WaitForChild("InnerYellowCore")
local glow=core:FindFirstChild("WarmFireGlow") or Instance.new("PointLight")
glow.Name="WarmFireGlow" glow.Color=Color3.fromRGB(255,154,52) glow.Brightness=2
glow.Range=16 glow.Shadows=false glow.Parent=core
local stream=water:WaitForChild("WaterStream")
local splash=water:WaitForChild("WaterSplash")

local camera=workspace.CurrentCamera
while not camera do workspace:GetPropertyChangedSignal("CurrentCamera"):Wait() camera=workspace.CurrentCamera end
camera.CameraType=Enum.CameraType.Scriptable camera.CameraSubject=nil camera.CFrame=CAMERA camera.FieldOfView=FOV

local flames,smoke={},{}
for _,q in ipairs(fire:GetDescendants()) do
	if q:IsA("BasePart") then
		local s={q,q.Size,q.Transparency}
		if q:IsDescendantOf(fire.StaticSmoke) then table.insert(smoke,s) else table.insert(flames,s) end
	end
end
local arms={}
for _,n in ipairs({"LeftRaisedSleeve","LeftRaisedForearm","LeftRaisedHand","RightRaisedSleeve","RightRaisedForearm","RightRaisedHand"}) do
	local q=resident:FindFirstChild(n) if q then arms[n]={q,q.CFrame} end
end
for _,n in ipairs({"LeftLeg","RightLeg","LeftShoe","RightShoe"}) do
	local q=resident:FindFirstChild(n) if q then q.Transparency=1 q.CastShadow=false end
end
local nozzleLocal=Vector3.new(4.6,3.2,0)
local function waterAlpha(a)
	local n=truck:GetPivot():PointToWorldSpace(nozzleLocal)
	stream.Size=Vector3.new((TARGET-n).Magnitude,.54,.54)
	stream.CFrame=CFrame.lookAt((n+TARGET)/2,TARGET)*CFrame.Angles(0,math.rad(90),0)
	splash.CFrame=CFrame.new(TARGET)
	stream.Transparency=1-.94*a splash.Transparency=1-.72*a
end
local function smooth(x) x=math.clamp(x,0,1) return x*x*(3-2*x) end

truck:PivotTo(START) waterAlpha(0)
print(("[RescuePreview] started; restored=%d"):format(restored))
local began=os.clock()
local marks={}
while true do
	local t=os.clock()-began
	preview:SetAttribute("SequenceTime",t)
	camera.CameraType=Enum.CameraType.Scriptable camera.CameraSubject=nil camera.CFrame=CAMERA camera.FieldOfView=FOV
	if t<1 then truck:PivotTo(START)
	elseif t<4 then
		truck:PivotTo(START:Lerp(FINISH,smooth((t-1)/3)))
		if not marks.move then marks.move=true print("[RescuePreview] truck moving") end
	else
		truck:PivotTo(FINISH)
		if not marks.arrive then marks.arrive=true print("[RescuePreview] truck arrived") end
	end
	local wa=0
	if t>=5 and t<5.25 then wa=(t-5)/.25 elseif t>=5.25 and t<7 then wa=1 elseif t>=7 and t<7.4 then wa=1-(t-7)/.4 end
	waterAlpha(math.clamp(wa,0,1))
	if t>=5 and not marks.water then marks.water=true print("[RescuePreview] water on") end
	local sup=smooth((t-6)/2)
	for _,s in ipairs(flames) do s[1].Size=s[2]:Lerp(s[2]*.48,sup) s[1].Transparency=s[3]+(.76-s[3])*sup end
	for _,s in ipairs(smoke) do s[1].Size=s[2]:Lerp(s[2]*.68,sup) s[1].Transparency=s[3]+(.84-s[3])*sup end
	glow.Brightness=2+(0.35-2)*sup
	if t>=6 and not marks.suppress then marks.suppress=true print("[RescuePreview] suppression started") end
	local w=math.sin(t*math.pi*3) local a=math.rad(7)*w
	if arms.LeftRaisedSleeve then arms.LeftRaisedSleeve[1].CFrame=arms.LeftRaisedSleeve[2]*CFrame.Angles(0,0,a*.5) end
	if arms.LeftRaisedForearm then arms.LeftRaisedForearm[1].CFrame=arms.LeftRaisedForearm[2]*CFrame.Angles(0,0,a) end
	if arms.RightRaisedSleeve then arms.RightRaisedSleeve[1].CFrame=arms.RightRaisedSleeve[2]*CFrame.Angles(0,0,-a*.5) end
	if arms.RightRaisedForearm then arms.RightRaisedForearm[1].CFrame=arms.RightRaisedForearm[2]*CFrame.Angles(0,0,-a) end
	if arms.LeftRaisedHand then arms.LeftRaisedHand[1].CFrame=arms.LeftRaisedHand[2]*CFrame.new(0,.1*w,0) end
	if arms.RightRaisedHand then arms.RightRaisedHand[1].CFrame=arms.RightRaisedHand[2]*CFrame.new(0,-.1*w,0) end
	if t>=8 then
		truck:PivotTo(FINISH) waterAlpha(0)
		for _,s in ipairs(flames) do s[1].Size=s[2]*.48 s[1].Transparency=.76 end
		for _,s in ipairs(smoke) do s[1].Size=s[2]*.68 s[1].Transparency=.84 end
		glow.Brightness=.35
		for _,s in pairs(arms) do s[1].CFrame=s[2] end
		print("[RescuePreview] complete") break
	end
	RunService.RenderStepped:Wait()
end
